<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);rxp_require_perm($ctx,'categories');$owner=rxp_target_reseller($ctx);$bot=rxp_bot_info($pdo,$owner);$flash='';$ft='ok';$q=$pdo->prepare('SELECT agent FROM user WHERE id=?');$q->execute([$owner]);$agentType=(string)$q->fetchColumn();if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$act=(string)($_POST['action']??'');try{if($act==='toggle'&&$bot){$setting=json_decode((string)$bot['setting'],true)?:[];$setting['statuscategorygenral']=isset($_POST['enabled'])?'oncategorys':'offcategorys';$pdo->prepare('UPDATE botsaz SET setting=? WHERE id_user=?')->execute([json_encode($setting,JSON_UNESCAPED_UNICODE),$owner]);$bot['setting']=json_encode($setting);$flash='وضعیت دسته‌بندی ذخیره شد.';}elseif($act==='add'){$name=mb_substr(trim((string)($_POST['name']??'')),0,191);if($name==='')throw new DomainException('نام لازم است.');$slug='rc-'.bin2hex(random_bytes(5));$pdo->prepare("INSERT INTO reseller_categories(reseller_id,name,slug,sort_order,status,created_at,updated_at) VALUES(?,?,?,?, 'active',?,?)")->execute([$owner,$name,$slug,max(0,(int)($_POST['sort']??0)),time(),time()]);$flash='دسته مستقل ساخته شد.';}elseif($act==='edit'){$id=(int)($_POST['id']??0);$name=mb_substr(trim((string)($_POST['name']??'')),0,191);$status=in_array((string)($_POST['status']??''),['active','disabled'],true)?$_POST['status']:'active';if($name==='')throw new DomainException('نام لازم است.');$pdo->prepare('UPDATE reseller_categories SET name=?,sort_order=?,status=?,updated_at=? WHERE id=? AND reseller_id=?')->execute([$name,max(0,(int)($_POST['sort']??0)),$status,time(),$id,$owner]);$flash='دسته ویرایش شد.';}elseif($act==='delete'){$id=(int)($_POST['id']??0);$pdo->beginTransaction();$pdo->prepare('DELETE FROM reseller_product_categories WHERE reseller_id=? AND category_id=?')->execute([$owner,$id]);$pdo->prepare('DELETE FROM reseller_categories WHERE reseller_id=? AND id=?')->execute([$owner,$id]);$pdo->commit();$flash='دسته حذف شد.';}elseif($act==='assign'){$id=(int)($_POST['category_id']??0);$code=trim((string)($_POST['product_code']??''));$q=$pdo->prepare('SELECT COUNT(*) FROM reseller_categories WHERE id=? AND reseller_id=?');$q->execute([$id,$owner]);if((int)$q->fetchColumn()!==1)throw new DomainException('دسته نامعتبر');$q=$pdo->prepare("SELECT COUNT(*) FROM product WHERE code_product=? AND (agent=? OR agent=? OR agent='all')");$q->execute([$code,$agentType,$owner]);if((int)$q->fetchColumn()!==1)throw new DomainException('محصول خارج محدوده است.');$pdo->prepare('INSERT INTO reseller_product_categories(reseller_id,product_code,category_id,created_at) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE category_id=VALUES(category_id)')->execute([$owner,$code,$id,time()]);$flash='محصول به دسته مستقل متصل شد.';}elseif($act==='unassign'){$code=(string)($_POST['product_code']??'');$pdo->prepare('DELETE FROM reseller_product_categories WHERE reseller_id=? AND product_code=?')->execute([$owner,$code]);$flash='اتصال حذف شد.';}rxp_audit($pdo,$ctx,'category.'.$act,$owner);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$flash=rxp_public_exception_message($e, basename(__FILE__));$ft='err';}}
$setting=$bot?(json_decode((string)$bot['setting'],true)?:[]):[];$enabled=($setting['statuscategorygenral']??'offcategorys')==='oncategorys';$q=$pdo->prepare('SELECT c.*,(SELECT COUNT(*) FROM reseller_product_categories m WHERE m.reseller_id=c.reseller_id AND m.category_id=c.id) products FROM reseller_categories c WHERE c.reseller_id=? ORDER BY c.sort_order,c.id');$q->execute([$owner]);$cats=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT p.code_product,p.name_product,p.agent,m.category_id,c.name category_name FROM product p LEFT JOIN reseller_product_categories m ON m.reseller_id=? AND m.product_code=p.code_product LEFT JOIN reseller_categories c ON c.id=m.category_id WHERE p.agent=? OR p.agent=? OR p.agent='all' ORDER BY p.name_product LIMIT 500");$q->execute([$owner,$agentType,$owner]);$products=$q->fetchAll(PDO::FETCH_ASSOC);rxp_layout_start($ctx,'دسته‌بندی مستقل','categories.php');rxp_flash($flash,$ft);?>
<h1 class="rxp-title">دسته‌بندی مستقل نماینده</h1><?php if($ctx['role']==='super'):?><div class="rxp-card"><form method="get"><select name="owner" onchange="this.form.submit()"><?php foreach($ctx['scope_ids']as$id):?><option value="<?=$id?>" <?=$owner===$id?'selected':''?>>نماینده #<?=$id?></option><?php endforeach;?></select></form></div><?php endif;?><div class="rxp-card"><form method="post"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><input type="hidden" name="action" value="toggle"><label><input type="checkbox" name="enabled" <?=$enabled?'checked':''?>> نمایش دسته‌بندی در ربات</label><button class="rxp-btn">ذخیره</button></form></div><div class="rxp-card"><h2>ساخت دسته</h2><form method="post" class="rxp-form"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><input type="hidden" name="action" value="add"><input name="name" placeholder="نام دسته" required><input type="number" name="sort" min="0" placeholder="ترتیب"><button class="rxp-btn green">افزودن</button></form></div><div class="rxp-card"><h2>دسته‌ها</h2><table class="rxp-table"><tr><th>نام</th><th>Slug</th><th>محصول</th><th>ویرایش</th></tr><?php foreach($cats as$c):?><tr><td><?=rxp_h($c['name'])?></td><td><code><?=rxp_h($c['slug'])?></code></td><td><?=$c['products']?></td><td><form method="post" class="rxp-form"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=$c['id']?>"><input name="name" value="<?=rxp_h($c['name'])?>"><input type="number" name="sort" value="<?=$c['sort_order']?>"><select name="status"><option value="active" <?=$c['status']==='active'?'selected':''?>>active</option><option value="disabled" <?=$c['status']==='disabled'?'selected':''?>>disabled</option></select><button class="rxp-btn">ذخیره</button></form><form method="post" onsubmit="return confirm('دسته و اتصال‌ها حذف شوند؟')"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="rxp-btn red">حذف</button></form></td></tr><?php endforeach;?></table></div><div class="rxp-card"><h2>اتصال محصولات</h2><table class="rxp-table"><tr><th>محصول</th><th>نوع</th><th>دسته فعلی</th><th>تغییر</th></tr><?php foreach($products as$p):?><tr><td><?=rxp_h($p['name_product'])?><br><code><?=rxp_h($p['code_product'])?></code></td><td><?=$p['agent']===$owner?'اختصاصی':'پایه'?></td><td><?=rxp_h($p['category_name']??'—')?></td><td><form method="post" class="rxp-form"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="product_code" value="<?=rxp_h($p['code_product'])?>"><select name="category_id" required><?php foreach($cats as$c):if($c['status']!=='active')continue;?><option value="<?=$c['id']?>" <?=$p['category_id']==$c['id']?'selected':''?>><?=rxp_h($c['name'])?></option><?php endforeach;?></select><button class="rxp-btn">اتصال</button></form><?php if($p['category_id']):?><form method="post"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><input type="hidden" name="action" value="unassign"><input type="hidden" name="product_code" value="<?=rxp_h($p['code_product'])?>"><button class="rxp-btn gray">حذف اتصال</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php rxp_layout_end();
